const CACHE='ruangrupa-v71';
const ASSETS=['./','./index.html','./catalog.js','./reviews.js','./admin-reviews.js','./stage13.js','./legal.css','./privacy.html','./terms.html','./returns.html','./404.html','./account.html','./account.js','./payment.html','./payment.js','./midtrans.js','./orders.html','./track.html','./track.js','./admin.html','./admin.js','./admin-settings.js','./admin-reports.js','./admin-promotions.js','./admin-stock.js','./admin-customers.js','./offline.html','./manifest.webmanifest','./assets/hero-furniture.webp','./assets/sofa-nara-illustration.png','./assets/icon-192.png','./assets/icon-512.png'];
self.addEventListener('install',event=>event.waitUntil(Promise.all([caches.open(CACHE).then(cache=>cache.addAll(ASSETS)),self.skipWaiting()])));
self.addEventListener('activate',event=>event.waitUntil(Promise.all([caches.keys().then(keys=>Promise.all(keys.filter(key=>key!==CACHE).map(key=>caches.delete(key)))),self.clients.claim()])));
self.addEventListener('fetch',event=>{const url=new URL(event.request.url);if(event.request.method!=='GET'||!['http:','https:'].includes(url.protocol)||url.origin!==self.location.origin)return;event.respondWith(fetch(event.request).then(response=>{if(response.ok){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(cache=>cache.put(event.request,copy)))}return response}).catch(()=>caches.match(event.request).then(hit=>hit||caches.match('./offline.html'))))});
